QUESTIONS = [
{"id":1,"topic":"SELECT 基础查询","type":"单选题","question":"查询 student 表中的所有字段，正确的 SQL 是？","options":["SELECT * FROM student;","GET * FROM student;","SELECT ALL student;","SHOW student;"],"answer":"SELECT * FROM student;","explanation":"SELECT * 表示查询表中的所有列，FROM 指定数据来源表。"},
{"id":2,"topic":"SELECT 基础查询","type":"单选题","question":"只查询 student 表中的 name 和 age 两列，应使用？","options":["SELECT name, age FROM student;","SELECT name AND age FROM student;","GET name, age student;","SELECT (name age) FROM student;"],"answer":"SELECT name, age FROM student;","explanation":"多个字段名之间使用逗号分隔。"},
{"id":3,"topic":"SELECT 基础查询","type":"单选题","question":"SQL 查询语句中，指定数据来源表的关键字是？","options":["FROM","WHERE","ORDER BY","GROUP BY"],"answer":"FROM","explanation":"FROM 用于指定查询所涉及的数据表。"},
{"id":4,"topic":"WHERE 条件筛选","type":"单选题","question":"查询成绩大于 80 分的记录，条件表达式应为？","options":["score > 80","score < 80","score = 80","score <> 80"],"answer":"score > 80","explanation":"大于使用 > 运算符，条件通常写在 WHERE 子句中。"},
{"id":5,"topic":"WHERE 条件筛选","type":"单选题","question":"查询年龄在 18 到 22 岁之间（包含边界），使用？","options":["age BETWEEN 18 AND 22","age IN 18 TO 22","age > 18 AND < 22","age RANGE 18,22"],"answer":"age BETWEEN 18 AND 22","explanation":"BETWEEN...AND... 表示闭区间，包含 18 和 22。"},
{"id":6,"topic":"WHERE 条件筛选","type":"单选题","question":"筛选 name 以“张”开头的记录，正确条件是？","options":["name LIKE '张%'","name = '张%'","name LIKE '%张'","name START '张'"],"answer":"name LIKE '张%'","explanation":"LIKE 配合 % 通配符，'张%' 表示以张开头的字符串。"},
{"id":7,"topic":"WHERE 条件筛选","type":"单选题","question":"同时满足 age >= 18 和 score >= 60，使用哪个逻辑运算符？","options":["AND","OR","NOT","XOR"],"answer":"AND","explanation":"AND 要求多个条件同时成立。"},
{"id":8,"topic":"ORDER BY 排序","type":"单选题","question":"按成绩从高到低排序，正确写法是？","options":["ORDER BY score DESC","ORDER BY score ASC","SORT score DOWN","GROUP BY score DESC"],"answer":"ORDER BY score DESC","explanation":"DESC 表示降序；ASC 表示升序。"},
{"id":9,"topic":"ORDER BY 排序","type":"单选题","question":"ORDER BY 默认的排序方向是？","options":["升序 ASC","降序 DESC","随机","不排序"],"answer":"升序 ASC","explanation":"未指定 ASC 或 DESC 时，默认按升序排列。"},
{"id":10,"topic":"ORDER BY 排序","type":"单选题","question":"先按班级升序，再按成绩降序，正确写法是？","options":["ORDER BY class ASC, score DESC","ORDER BY class DESC, score ASC","ORDER BY class AND score","GROUP BY class, score"],"answer":"ORDER BY class ASC, score DESC","explanation":"ORDER BY 可以指定多个排序字段，每个字段可分别指定方向。"},
{"id":11,"topic":"聚合函数","type":"单选题","question":"统计 student 表中的记录总数，使用？","options":["COUNT(*)","SUM(*)","TOTAL(*)","NUMBER(*)"],"answer":"COUNT(*)","explanation":"COUNT(*) 统计结果集中的行数。"},
{"id":12,"topic":"聚合函数","type":"单选题","question":"计算 score 字段的平均值，使用？","options":["AVG(score)","MEAN(score)","AVERAGE(score)","COUNT(score)"],"answer":"AVG(score)","explanation":"AVG() 用于计算数值列的平均值。"},
{"id":13,"topic":"聚合函数","type":"单选题","question":"求 score 字段的最高值，使用？","options":["MAX(score)","HIGH(score)","TOP(score)","UPPER(score)"],"answer":"MAX(score)","explanation":"MAX() 返回指定列的最大值。"},
{"id":14,"topic":"GROUP BY 分组","type":"单选题","question":"若要统计每个班级的人数，通常需要使用？","options":["GROUP BY class","ORDER BY class","WHERE class","DISTINCT class"],"answer":"GROUP BY class","explanation":"GROUP BY 按一个或多个字段分组，常与 COUNT 等聚合函数配合。"},
{"id":15,"topic":"GROUP BY 分组","type":"单选题","question":"分组后筛选人数大于 10 的班级，应使用？","options":["HAVING COUNT(*) > 10","WHERE COUNT(*) > 10","ORDER BY COUNT(*) > 10","LIMIT COUNT(*) > 10"],"answer":"HAVING COUNT(*) > 10","explanation":"HAVING 用于对分组后的结果进行条件筛选。"},
{"id":16,"topic":"GROUP BY 分组","type":"单选题","question":"SQL 中 WHERE 和 HAVING 的常见区别是？","options":["WHERE 过滤分组前记录，HAVING 过滤分组结果","两者完全相同","HAVING 只能排序","WHERE 只能配合 COUNT"],"answer":"WHERE 过滤分组前记录，HAVING 过滤分组结果","explanation":"WHERE 通常在分组前筛选行；HAVING 对 GROUP BY 形成的分组进行筛选。"},
{"id":17,"topic":"综合查询","type":"单选题","question":"SQL 查询语句中，通常用于限制返回记录数量的关键字是？","options":["LIMIT","COUNT","GROUP","RANGE"],"answer":"LIMIT","explanation":"在 MySQL 中，LIMIT 可限制返回的行数。"},
{"id":18,"topic":"综合查询","type":"单选题","question":"查询结果中去除重复的班级名称，使用？","options":["SELECT DISTINCT class FROM student;","SELECT UNIQUE class FROM student;","SELECT class ONLY FROM student;","REMOVE DUPLICATE class;"],"answer":"SELECT DISTINCT class FROM student;","explanation":"DISTINCT 用于去除查询结果中的重复行。"},
{"id":19,"topic":"综合查询","type":"单选题","question":"以下 SQL 子句的常见书写顺序，哪项正确？","options":["SELECT-FROM-WHERE-GROUP BY-HAVING-ORDER BY","FROM-SELECT-ORDER BY-WHERE","WHERE-SELECT-FROM-GROUP BY","SELECT-WHERE-FROM-HAVING"],"answer":"SELECT-FROM-WHERE-GROUP BY-HAVING-ORDER BY","explanation":"这是常见的 SQL 查询语句书写顺序。"},
{"id":20,"topic":"综合查询","type":"单选题","question":"查询成绩不低于 60 分且按成绩降序排列，正确写法是？","options":["SELECT * FROM student WHERE score >= 60 ORDER BY score DESC;","SELECT * FROM student ORDER BY score WHERE score >= 60;","SELECT student WHERE score >= 60 DESC;","GET * FROM student WHERE score >= 60;"],"answer":"SELECT * FROM student WHERE score >= 60 ORDER BY score DESC;","explanation":"先用 WHERE 筛选，再用 ORDER BY 排序；DESC 表示降序。"},
]
